mapper.select:
SELECT * FROM mdf_backfill_task

    AND status = #{status}

ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE mdf_backfill_task SET status = 'PAUSED', claim_token = NULL,
    finished_at = NULL, updated_at = #{now}
WHERE id = #{id} AND status = 'RUNNING'

mapper.select:
SELECT COUNT(1) FROM mdf_backfill_task
WHERE dataset_code = #{datasetCode} AND provider_code = #{providerCode}
  AND adjust_type = #{adjustType} AND start_date = #{startDate} AND end_date = #{endDate}
  AND symbols_hash = #{symbolsHash}
  AND status IN ('PENDING', 'RUNNING', 'PAUSED')
